MANIFEST="app/src/main/AndroidManifest.xml"
if ! grep -q "MusicHomeActivity" "$MANIFEST"; then
    python3 << 'PYEOF2'
manifest = "app/src/main/AndroidManifest.xml"
with open(manifest, 'r', encoding='utf-8') as f:
    c = f.read()
old = '<activity android:name=".ui.activity.LxMusicSearchActivity"'
new = old + ' />\n        <activity android:name=".ui.activity.MusicHomeActivity"'
if old in c and "MusicHomeActivity" not in c:
    c = c.replace(old, new)
    with open(manifest, 'w', encoding='utf-8') as f:
        f.write(c)
    print("MusicHomeActivity 已注册")
PYEOF2
fi

